contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        // Record all public L1 block values before the attempted change.
        uint64 beforeNumber = c.number();
        uint64 beforeTimestamp = c.timestamp();
        uint256 beforeBasefee = c.basefee();
        bytes32 beforeHash = c.hash();
        uint64 beforeSequenceNumber = c.sequenceNumber();
        bytes32 beforeBatcherHash = c.batcherHash();
        uint256 beforeL1FeeOverhead = c.l1FeeOverhead();
        uint256 beforeL1FeeScalar = c.l1FeeScalar();

        // This test contract is not the depositor, so this call must revert.
        bool reverted;
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read all public L1 block values after the attempted change.
        uint64 afterNumber = c.number();
        uint64 afterTimestamp = c.timestamp();
        uint256 afterBasefee = c.basefee();
        bytes32 afterHash = c.hash();
        uint64 afterSequenceNumber = c.sequenceNumber();
        bytes32 afterBatcherHash = c.batcherHash();
        uint256 afterL1FeeOverhead = c.l1FeeOverhead();
        uint256 afterL1FeeScalar = c.l1FeeScalar();

        assert(
            reverted &&
            afterNumber == beforeNumber &&
            afterTimestamp == beforeTimestamp &&
            afterBasefee == beforeBasefee &&
            afterHash == beforeHash &&
            afterSequenceNumber == beforeSequenceNumber &&
            afterBatcherHash == beforeBatcherHash &&
            afterL1FeeOverhead == beforeL1FeeOverhead &&
            afterL1FeeScalar == beforeL1FeeScalar
        );
    }

    receive() external payable {}
}

